{
  "goalId": "dfd2628f-b44e-51b3-86e8-99158861be8c",
  "candidateDecision": "accept",
  "semanticKind": "practiceAssessment",
  "semanticKindReason": "Die versiegelte Fassung enthält eine zweiteilige Übungsprüfung mit vorgegebenen Daten, Arbeitsaufträgen, Musterlösung, Punkteverteilung und Bestehensgrenze. Sie prüft mehrere Leistungen an einem konkreten Fall. Die technische Kennzeichnung „atomic“ ändert diese fachliche Einordnung nicht.",
  "physicsAndLanguage": "Beide Sprachfassungen definieren den Sicherheitsabstand als freien Anhalteweg vor einem stehenden Hindernis. Beim Wurf ergeben die Daten x/t = 2,0 m/s und Fallstrecke/t² ≈ 5,00, 5,00 und 4,89 m/s². Die gemeinsame Zeit verknüpft beide Bewegungen zu einer näherungsweise parabelförmigen Bahn. Eine konsistente Wahl der Fallrichtung und getrennte Wertespalten über derselben Zeit sind zulässig. Eigene Aufnahmen und Messfehlergrenzen werden nicht verlangt. In Teil B ergeben sich rund 27,9 m und 83,8 m Anhalteweg. Die zwei Bremswerte belegen die Vervierfachung für den vorgegebenen Vergleich. Eine Verallgemeinerung auf beliebige Fahrbedingungen lässt sich daraus nicht ableiten.",
  "scopeVerdict": "Die Unterlagen tragen den Einsatz als gymnasiale Sek-I-Übungsaufgabe mit Anforderungen von AB1 bis AB3. Der Wurf und die Modellgrenze liefern Stützpunkte. Das direkt abgedeckte Ziel betrifft die Verkehrsbewertung. Die von Voraussetzungen geerbte Länderzuordnung, der Schlüssel mit BW/BY und die Tags GK/LK belegen weder ein tatsächliches Prüfungsangebot noch eine amtliche Landesprüfung oder eine verbindliche Kursanforderung. Die Freigabeentscheidung dieser Blindrunde betrifft die Kurzfassung. Der übernommene reviewStatus belegt keine Aktivierung.",
  "scoringConsistency": "Teil A ergibt 4 BE, Teil B 12 BE. Bestanden ist allein bei mindestens 12 von 16 BE. Der vollständige Ausfall von P_ANHALT lässt höchstens 10 BE, der von P_BEWERT höchstens 11 BE zu. Auch die 0,5-BE-Stufe im Urteil reicht bei sonst voller Leistung mit 11,5 BE nicht zum Bestehen. Umgekehrt können vier richtige, unbelegte Fallwerte in B_RW und B_AW zusammen 2 BE ergeben und mit den übrigen 10 BE genau ausreichen. Ein Bestehen bescheinigt daher keine vollständige rechnerische Herleitung. Die Kurzfassung erhält diese Schwellen und die einmalige Belastung lokaler Fehler.",
  "stepCompressionChecks": [
    {
      "criterionId": "B_RW",
      "equivalent": true,
      "reason": "Die deutsche und englische Kurzfassung erhalten zusammen mit dem Abschnitt B_RW die Wertung je Geschwindigkeitsfall. Auch eine begründete Verdopplung bei gleicher Reaktionszeit zählt voll, ein bloßer richtiger Wert zählt 0,5 BE. Bei 50 : 3,6 = 13,2 und folgerichtig verdoppelten 26,4 m ergeben sich 1 + 1,5 = 2,5 BE. Fehlt der zweite Fall, bleibt es bei 1 BE. Wer ohne Umrechnungsversuch mit 50 und 100 als m/s rechnet, erhält 1 + 1 = 2 BE. Folgerichtige Summen und Vergleiche bleiben jeweils unbelastet. Die gemeinsamen Fehlerhinweise unterscheiden ein isoliertes Formelversehen vom begründeten und beibehaltenen Divisionsmodell, das B_RW und B_AW zusammen auf null setzt."
    },
    {
      "criterionId": "B_URT",
      "equivalent": true,
      "reason": "In beiden Sprachen bleibt die höchste zutreffende Stufe maßgeblich. Der Verweis erhält insbesondere den additiven Weg zu 5 BE. Werden +13,9 m dem Reaktionsweg und +42 m dem Bremsweg zugeordnet, begründen zusammen +55,9 m gegenüber nur +27,9 m bei Verdopplung den Abstandsschluss. Ein reiner Gesamtvergleich mit Entscheidung erhält 0,5 BE. Die Entscheidung mit genau einer gedeuteten Änderung erhält 4 BE, sofern die andere unwidersprochen bleibt. Beide Änderungen ohne Abstandsschluss ergeben 0,5 BE. Ein vollständiger Kern mit lokalem Schnitzer ergibt 4,5 BE. Ein bloßes „falsch“ oder eine ausdrücklich vertretene und beibehaltene falsche Skalierung ergibt 0 BE in B_URT. Der Abschnitt B_URT klärt dies auch für das englische „defended scaling misconception“."
    }
  ],
  "carryingPerformanceAudit": [
    {
      "performanceId": "P_ANHALT",
      "earnedFromTask": "Für 50 und 100 km/h den während 1,0 s zurückgelegten Reaktionsweg bestimmen und jeweils den gegebenen Bremsweg addieren. B_RW und B_AW tragen je 3 BE.",
      "weight": 6,
      "completeOmissionMaximum": 10,
      "safeguardsAndLimits": "Sichtbare, folgerichtige Summen mit einem bereits belasteten Reaktionsweg zählen voll. Ganze Meter sind zulässig. Eine ausdrücklich vertretene falsche Abhängigkeit von der Reaktionszeit oder ein begründet subtrahierender Anhalteweg entwertet die gesamte Gruppe. Ein unabhängig richtiges Skalierungsurteil zählt weiter."
    },
    {
      "performanceId": "P_BEWERT",
      "earnedFromTask": "Den nötigen freien Abstand vor dem stehenden Hindernis beurteilen und den Schluss mit den Änderungen von Reaktionsweg und gegebenem Bremsweg verknüpfen. B_URT trägt 5 BE.",
      "weight": 5,
      "completeOmissionMaximum": 11,
      "safeguardsAndLimits": "Ein eindeutiger rechnerischer Abstandsschluss genügt als Entscheidung. Faktor-, Proportionalitäts- und zugeordnete Zuwachsargumente sind gleichwertig. Der ungefähre Gesamtfaktor drei ist optional. Eine beibehaltene falsche Skalierung entwertet B_URT auch bei richtigem Endurteil. Unabhängig belegte Rechnungen und Stützpunkte bleiben anrechenbar."
    }
  ],
  "coveredGoalReviews": [
    {
      "goalId": "4a2bf015-052b-4af0-aed7-324259fa1a8a",
      "mustShow": "Die volle Zielleistung verbindet die Modellrechnung für beide Geschwindigkeiten mit einer begründeten Abstandsentscheidung. Bei fester Reaktionszeit verdoppelt sich der Reaktionsweg, der gegebene Bremsweg vervierfacht sich und die Summe wächst auf mehr als das Doppelte. Bei einer bestandenen Arbeit müssen rechnerisch mindestens 2 BE aus P_ANHALT und wegen der Urteilsstufen mindestens 4 BE aus P_BEWERT erkennbar sein.",
      "mayRemainOpen": "Einzelne Fallrechnungen oder bei einem 4-BE-Urteil die Deutung des zweiten Anteils dürfen fehlen. Der genaue Abstandsquotient, ein allgemeines Bremsgesetz und der Folgeabstand zu einem fahrenden Fahrzeug sind für die Beurteilung dieses Falls entbehrlich.",
      "whyTolerable": "Das Ziel wird an einer konkreten Alltagssituation mit zwei gegebenen Bremswegen geprüft. Bereits eine richtig gedeutete Einzeländerung mit tragfähigem Abstandsschluss zeigt eine Teilleistung im Bewerten. Ein vollständiger Ausfall der Modellrechnung oder der Bewertung schließt das Bestehen rechnerisch aus. Die Übertragung auf ein bewegtes Vorderfahrzeug würde zusätzliche Bewegungsdaten erfordern."
    }
  ],
